import csv
import io


def import_text(text, store, dry_run=False):
    items = _parse(text)
    result = {'created': 0, 'updated': 0, 'unchanged': 0, 'changes': []}
    changed = []
    for item in items:
        before = store.get(item['sku'])
        if before == item:
            result['unchanged'] += 1
            continue
        changed.append(item)
        result['created' if before is None else 'updated'] += 1
        result['changes'].append({'sku': item['sku'], 'before': before, 'after': item})
    if not dry_run:
        for item in changed:
            store.put(item)
    return result


def _parse(text):
    items = []
    reader = csv.DictReader(io.StringIO(text))
    for row in reader:
        sku = _clean(row, 'sku')
        name = _clean(row, 'name')
        qty = _clean(row, 'qty')
        if not sku:
            raise ValueError('row has empty sku')
        if not name:
            raise ValueError('row has empty name')
        if not qty.isascii() or not qty.isdigit():
            raise ValueError('row has invalid quantity')
        items.append({'sku': sku, 'name': name, 'qty': int(qty)})
    return items


def _clean(row, field):
    value = row.get(field)
    return '' if value is None else value.strip()

